// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// GetHealthLive Unauthenticated daemon liveness check.
	// (GET /health/live)
	GetHealthLive(ctx context.Context, request GetHealthLiveRequestObject) (GetHealthLiveResponseObject, error)
	// GetSessions List all leases.
	// (GET /sessions)
	GetSessions(ctx context.Context, request GetSessionsRequestObject) (GetSessionsResponseObject, error)
	// PostSessions Create a lease against a module TCP host:port or chardev path.
	// (POST /sessions)
	PostSessions(ctx context.Context, request PostSessionsRequestObject) (PostSessionsResponseObject, error)
	// DeleteSessionsId Idempotently force-close and remove a lease, even while busy.
	// (DELETE /sessions/{id})
	DeleteSessionsId(ctx context.Context, request DeleteSessionsIdRequestObject) (DeleteSessionsIdResponseObject, error)
	// GetSessionsId Inspect a lease's state, destination, cached INFO, and expiry.
	// (GET /sessions/{id})
	GetSessionsId(ctx context.Context, request GetSessionsIdRequestObject) (GetSessionsIdResponseObject, error)
	// PostSessionsIdCommandsEcho Send ECHO on this lease's session. Binary data is base64.
	// (POST /sessions/{id}/commands/echo)
	PostSessionsIdCommandsEcho(ctx context.Context, request PostSessionsIdCommandsEchoRequestObject) (PostSessionsIdCommandsEchoResponseObject, error)
	// PostSessionsIdCommandsInfo Send INFO on this lease's session.
	// (POST /sessions/{id}/commands/info)
	PostSessionsIdCommandsInfo(ctx context.Context, request PostSessionsIdCommandsInfoRequestObject) (PostSessionsIdCommandsInfoResponseObject, error)
	// PostSessionsIdCommandsPslist Send PSLIST on this lease's session, returning semantic process/thread JSON. requested_groups defaults to the module's supported set if omitted.
	// (POST /sessions/{id}/commands/pslist)
	PostSessionsIdCommandsPslist(ctx context.Context, request PostSessionsIdCommandsPslistRequestObject) (PostSessionsIdCommandsPslistResponseObject, error)
	// PostSessionsIdRenew Refresh an idle lease's expiry.
	// (POST /sessions/{id}/renew)
	PostSessionsIdRenew(ctx context.Context, request PostSessionsIdRenewRequestObject) (PostSessionsIdRenewResponseObject, error)
	// GetStatus Authenticated daemon information.
	// (GET /status)
	GetStatus(ctx context.Context, request GetStatusRequestObject) (GetStatusResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

